<template>
  <div>
    <PageHeader title="Reports and segments" eyebrow="Insights &amp; care" subtitle="Understand your church community and turn insights into thoughtful follow-up."><template #actions><v-btn v-if="auth.hasPermission('followups.work')" to="/followups">Follow-up tasks</v-btn></template></PageHeader>
    <v-alert v-if="error" type="error" class="mb-4">{{ error }}</v-alert>
    <v-card class="workspace-panel"><div class="panel-heading"><div class="panel-heading__copy"><v-icon icon="mdi-chart-box-outline" /><div><h2>Operational report</h2><p>A clear view of people, participation and giving.</p></div></div></div><div class="workspace-form-row"><v-text-field v-model="from" type="date" label="Report from" /><v-text-field v-model="to" type="date" label="Report to" /></div><div class="workspace-actions"><v-btn color="primary" :loading="busy" @click="loadSummary">Run report</v-btn><v-btn v-if="summary" :disabled="busy" @click="download('/api/reports/summary.csv',{from,to},'operational-report.csv')" variant="outlined" prepend-icon="mdi-download-outline">Export report CSV</v-btn></div>
      <p class="mt-3">Only sections permitted by your role appear. Dates cover attendance and giving; People and ministry membership counts reflect current records.</p>
      <v-alert v-if="summary && !Object.keys(summary.sections).length" type="info">Your account needs access to a source context to see report sections.</v-alert>
      <div v-if="summary" class="workspace-insights">
        <div v-if="summary.sections.people" class="workspace-insight"><div class="page-header__eyebrow">Community</div><h3>People · {{ summary.sections.people.total }}</h3><dl><div v-for="(count,status) in summary.sections.people.byStatus" :key="status"><dt>{{ status }}</dt><dd>{{ count }}</dd></div></dl></div>
        <div v-if="summary.sections.attendance" class="workspace-insight workspace-insight--wide"><h3>Attendance · {{ summary.sections.attendance.uniquePeoplePresent }} unique people present</h3><v-table><thead><tr><th>Date</th><th>Named present</th><th>Recorded absent</th><th>Excused</th><th>Visitors</th></tr></thead><tbody><tr v-for="day in summary.sections.attendance.days" :key="day.date"><td>{{ day.date }}</td><td>{{ day.present }}</td><td>{{ day.absent }}</td><td>{{ day.excused }}</td><td>{{ day.visitors }}</td></tr></tbody></v-table><div class="attendance-chart" aria-label="Named attendance by date"><div v-for="day in summary.sections.attendance.days" :key="day.date"><span>{{ day.date }}</span><meter :value="day.present" :max="chartMax" :aria-label="day.date + ' named present: ' + day.present" /> {{ day.present }}</div></div></div>
        <div v-if="summary.sections.ministries" class="workspace-insight"><h3>Ministry memberships</h3><p v-for="group in summary.sections.ministries.items" :key="group.id">{{ group.name }} · {{ group.members }} active members{{ group.active ? '' : ' · archived' }}</p></div>
        <div v-if="summary.sections.giving" class="workspace-insight"><h3>Giving by currency</h3><p v-for="total in summary.sections.giving.totals" :key="total.currency">{{ total.currency }} · gross {{ money(total.grossAmountMinor,total.currency) }} · reversals {{ money(total.reversalAmountMinor,total.currency) }} · net {{ money(total.netAmountMinor,total.currency) }}</p></div>
        <p class="workspace-insight--wide workspace-note">{{ summary.notice }}</p>
      </div>
    </v-card>
    <v-card v-if="auth.hasPermission('people.read')" class="workspace-panel"><div class="panel-heading"><div class="panel-heading__copy"><v-icon icon="mdi-account-filter-outline" /><div><h2>Saved People segments</h2><p>Find the people who need your attention with reusable filters.</p></div></div><v-btn v-if="manage" color="primary" prepend-icon="mdi-plus" @click="editSegment(null)">Create segment</v-btn></div><div v-if="!segments.length" class="workspace-empty"><v-icon icon="mdi-account-search-outline" size="36" /><p>No saved segments yet.</p></div><v-list><v-list-item v-for="segment in segments" :key="segment.id" :title="segment.name"><template #append><v-btn :disabled="busy" @click="evaluate(segment)">View people</v-btn><v-btn v-if="manage" :disabled="busy" @click="editSegment(segment)">Edit filters</v-btn></template></v-list-item></v-list>
      <div v-if="members"><h3>{{ members.segment.name }} · {{ members.count }} matches</h3><p>{{ members.notice }}</p><v-btn :disabled="busy" @click="download('/api/reports/segments/' + members.segment.id + '/members.csv',{},'segment-members.csv')">Export segment CSV</v-btn>
        <v-table><thead><tr><th>Person</th><th>Status</th><th>Age</th><th v-if="tasksManage">Follow-up</th></tr></thead><tbody><tr v-for="person in members.items" :key="person.id"><td>{{ person.name }}</td><td>{{ person.status }}</td><td>{{ person.age ?? 'Unknown' }}</td><td v-if="tasksManage"><v-btn :disabled="busy" @click="openTask(person)">Create follow-up</v-btn></td></tr></tbody></v-table>
      </div>
    </v-card>
    <v-card v-if="tasksManage && auth.hasPermission('people.read')" class="workspace-panel"><div class="panel-heading"><div class="panel-heading__copy"><v-icon icon="mdi-clipboard-check-outline" /><div><h2>Follow-up automation</h2><p>Keep care consistent with reviewed task assignments.</p></div></div></div><p>Rules start disabled. Enable only after reviewing the segment and assignment. They create at most one task per person and rule, including previously completed tasks. They never send messages.</p><v-btn v-if="manage" color="primary" prepend-icon="mdi-plus" class="my-3" @click="editRule(null)">Create automation rule</v-btn><v-list><v-list-item v-for="rule in rules" :key="rule.id" :title="rule.name" :subtitle="rule.reviewReason ?? (rule.active ? 'Enabled · last run ' + (rule.lastRunAt ?? 'never') : 'Disabled')"><template #append><v-btn v-if="manage" :disabled="busy" @click="editRule(rule)">Review rule</v-btn><v-btn v-if="manage" :disabled="busy || !rule.active" @click="run(rule)">Evaluate now</v-btn></template></v-list-item></v-list><v-alert v-if="runMessage" type="info">{{ runMessage }}</v-alert></v-card>
    <v-dialog v-model="segmentDialog" max-width="650" persistent><v-card title="People segment"><v-card-text><v-alert v-if="dialogError" type="error">{{ dialogError }}</v-alert><v-text-field v-model="segmentName" label="Segment name" maxlength="200" /><v-select v-model="status" :items="['prospect','active','inactive','transferred','deceased']" label="Membership status" clearable /><v-select v-model="ageGroup" :items="['adult','child']" label="Age group" clearable /><v-select v-if="auth.hasPermission('ministries.manage')" v-model="ministryId" :items="ministries" item-title="name" item-value="id" label="Active ministry membership" clearable /><v-select v-if="auth.hasPermission('attendance.manage')" v-model="attendanceStatus" :items="attendanceOptions" label="Attendance condition" clearable /><v-select v-if="attendanceStatus" v-model="periodMode" :items="[{title:'Rolling period',value:'rolling'},{title:'Fixed dates',value:'fixed'}]" label="Attendance period" /><div v-if="attendanceStatus && periodMode === 'fixed'"><v-text-field v-model="segmentFrom" type="date" label="Attendance from" /><v-text-field v-model="segmentTo" type="date" label="Attendance to" /></div><v-text-field v-if="attendanceStatus && periodMode === 'rolling'" v-model.number="lookbackDays" type="number" min="1" max="366" label="Look back this many days (including today)" /><p>Unknown birthdays do not match age filters. No recorded presence is not proof of absence.</p><v-btn :disabled="busy" @click="preview">Preview matches</v-btn><p v-if="previewCount !== null">{{ previewCount }} current matches</p></v-card-text><v-card-actions><v-btn :disabled="busy" @click="segmentDialog = false">Close</v-btn><v-btn :loading="busy" :disabled="!segmentName.trim()" @click="saveSegment">Save segment</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="taskDialog" max-width="600" persistent><v-card title="Create follow-up"><v-card-text><v-alert v-if="dialogError" type="error">{{ dialogError }}</v-alert><p>{{ taskPerson?.name }}</p><v-text-field v-model="taskTitle" label="Follow-up title" maxlength="200" /><v-select v-model="assigneeId" :items="assignees" item-title="username" item-value="id" label="Accountable staff account" /><v-text-field v-model="dueOn" type="date" label="Follow-up due on" /><p>Only active staff with follow-up and source permissions can be assigned.</p></v-card-text><v-card-actions><v-btn :disabled="busy" @click="taskDialog = false">Close</v-btn><v-btn :disabled="!taskTitle.trim() || !assigneeId || !dueOn" :loading="busy" @click="saveTask">Create task</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="ruleDialog" max-width="650" persistent><v-card title="Follow-up automation rule"><v-card-text><v-alert v-if="dialogError" type="error">{{ dialogError }}</v-alert><v-text-field v-model="ruleName" label="Rule name" maxlength="200" /><v-select v-model="ruleSegmentId" :items="segments" item-title="name" item-value="id" label="Rule segment" @update:model-value="loadRuleAssignees" /><v-text-field v-model="ruleTitle" label="Generated task title" maxlength="200" /><v-select v-model="assigneeId" :items="assignees" item-title="username" item-value="id" label="Responsible staff account" /><v-text-field v-model.number="dueInDays" type="number" min="0" max="90" label="Days until due" /><v-checkbox v-model="ruleActive" label="Enable daily task creation for this reviewed segment" /><p>Changes to a segment or staff access pause its automation for review.</p></v-card-text><v-card-actions><v-btn :disabled="busy" @click="ruleDialog = false">Close</v-btn><v-btn :loading="busy" :disabled="!ruleName.trim() || !ruleTitle.trim() || !ruleSegmentId || !assigneeId" @click="saveRule">Save automation rule</v-btn></v-card-actions></v-card></v-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import PageHeader from '@/components/common/PageHeader.vue'
import { useAuthStore } from '@/stores/auth'
import { extractErrorMessage, useApi } from '@/composables/useApi'
interface Segment {id:string,name:string,filters:Record<string,unknown>,version:number}
interface Person {id:string,name:string,status:string,age:number | null}
interface Rule {id:string,name:string,segmentId:string,segmentVersion:number,assigneeId:string,taskTitle:string,dueInDays:number,active:boolean,lastRunAt:string | null,reviewReason:string | null,version:number}
interface Day {date:string,present:number,absent:number,excused:number,visitors:number}
interface Summary {notice:string,sections:{people?:{total:number,byStatus:Record<string,number>},attendance?:{days:Day[],uniquePeoplePresent:number},ministries?:{items:{id:string,name:string,active:boolean,members:number}[]},giving?:{totals:{currency:string,grossAmountMinor:number,reversalAmountMinor:number,netAmountMinor:number}[]}}}
const auth = useAuthStore(), manage = computed(() => auth.hasPermission('reports.manage')), tasksManage = computed(() => auth.hasPermission('followups.manage'))
const error = ref(''), dialogError = ref(''), busy = ref(false), summary = ref<Summary | null>(null), from = ref(new Date().getUTCFullYear() + '-01-01'), to = ref(new Date().toISOString().slice(0,10))
const segments = ref<Segment[]>([]), rules = ref<Rule[]>([]), members = ref<{segment:Segment,items:Person[],count:number,notice:string} | null>(null), ministries = ref<{id:string,name:string}[]>([])
const segmentDialog = ref(false), editingSegment = ref<Segment | null>(null), segmentName = ref(''), status = ref<string | null>('active'), ageGroup = ref<string | null>(null), ministryId = ref<string | null>(null), attendanceStatus = ref<string | null>(null), lookbackDays = ref(30), previewCount = ref<number | null>(null)
const periodMode = ref('rolling'), segmentFrom = ref(from.value), segmentTo = ref(to.value)
const attendanceOptions = [{title:'Recorded present',value:'present'},{title:'Recorded absent',value:'absent'},{title:'No recorded presence',value:'no_recorded_presence'}]
const filters = computed(() => ({...(status.value ? {status:status.value}:{}),...(ageGroup.value ? {ageGroup:ageGroup.value}:{}),...(ministryId.value ? {ministryId:ministryId.value}:{}),...(attendanceStatus.value ? {attendanceStatus:attendanceStatus.value,...(periodMode.value === 'rolling' ? {lookbackDays:lookbackDays.value} : {from:segmentFrom.value,to:segmentTo.value})}:{})}))
watch(filters, () => {previewCount.value = null})
const assignees = ref<{id:string,username:string}[]>([]), assigneeId = ref<string | null>(null), taskDialog = ref(false), taskPerson = ref<Person | null>(null), taskTitle = ref(''), dueOn = ref(to.value)
const ruleDialog = ref(false), editingRule = ref<Rule | null>(null), ruleName = ref(''), ruleSegmentId = ref<string | null>(null), ruleTitle = ref(''), dueInDays = ref(7), ruleActive = ref(false), runMessage = ref('')
const chartMax = computed(() => Math.max(1,...(summary.value?.sections.attendance?.days.map(d => d.present) ?? [])))
async function action (operation:() => Promise<void>, dialog = false) {if (busy.value) return; busy.value = true; error.value = ''; dialogError.value = ''; try {await operation()} catch (e) {const message = extractErrorMessage(e,'Unable to complete this report operation.'); if (dialog) dialogError.value = message; else error.value = message} finally {busy.value = false}}
async function refresh () {if (auth.hasPermission('people.read')) segments.value = (await useApi().get<{items:Segment[]}>('/api/reports/segments')).data.items; if (tasksManage.value && auth.hasPermission('people.read')) rules.value = (await useApi().get<{items:Rule[]}>('/api/reports/rules')).data.items}
async function loadSummary () {summary.value = null; await action(async () => {summary.value = (await useApi().get<Summary>('/api/reports/summary',{params:{from:from.value,to:to.value}})).data})}
async function evaluate (segment:Segment) {members.value = null; await action(async () => {members.value = (await useApi().get('/api/reports/segments/' + segment.id + '/members')).data})}
async function editSegment (segment:Segment | null) {editingSegment.value = segment; segmentName.value = segment?.name ?? ''; status.value = (segment?.filters.status as string) ?? 'active'; ageGroup.value = (segment?.filters.ageGroup as string) ?? null; ministryId.value = (segment?.filters.ministryId as string) ?? null; attendanceStatus.value = (segment?.filters.attendanceStatus as string) ?? null; lookbackDays.value = Number(segment?.filters.lookbackDays ?? 30); periodMode.value = segment?.filters.from ? 'fixed' : 'rolling'; segmentFrom.value = String(segment?.filters.from ?? from.value); segmentTo.value = String(segment?.filters.to ?? to.value); previewCount.value = null; dialogError.value = ''; segmentDialog.value = true; if (auth.hasPermission('ministries.manage')) await action(async () => {ministries.value = (await useApi().get('/api/ministries')).data.ministries},true)}
async function preview () {await action(async () => {previewCount.value = (await useApi().post<{count:number}>('/api/reports/segments/preview',{filters:filters.value})).data.count},true)}
async function saveSegment () {await action(async () => {const payload = {name:segmentName.value,filters:filters.value,...(editingSegment.value ? {expectedVersion:editingSegment.value.version}:{})}; if (editingSegment.value) await useApi().put('/api/reports/segments/' + editingSegment.value.id,payload); else await useApi().post('/api/reports/segments',payload); segmentDialog.value = false; members.value = null; await refresh()},true)}
async function openTask (person:Person) {taskPerson.value = person; taskTitle.value = ''; dueOn.value = to.value; assigneeId.value = null; dialogError.value = ''; await action(async () => {assignees.value = (await useApi().get('/api/reports/assignees',{params:{segmentId:members.value?.segment.id}})).data.items; taskDialog.value = true})}
async function saveTask () {await action(async () => {await useApi().post('/api/followups',{personId:taskPerson.value?.id,assigneeId:assigneeId.value,title:taskTitle.value,dueOn:dueOn.value,segmentId:members.value?.segment.id}); taskDialog.value = false},true)}
async function loadRuleAssignees () {assigneeId.value = null; assignees.value = []; if (ruleSegmentId.value) await action(async () => {assignees.value = (await useApi().get('/api/reports/assignees',{params:{segmentId:ruleSegmentId.value}})).data.items},true)}
async function editRule (rule:Rule | null) {editingRule.value = rule; ruleName.value = rule?.name ?? ''; ruleSegmentId.value = rule?.segmentId ?? null; ruleTitle.value = rule?.taskTitle ?? ''; dueInDays.value = rule?.dueInDays ?? 7; ruleActive.value = rule?.active ?? false; dialogError.value = ''; ruleDialog.value = true; await loadRuleAssignees(); assigneeId.value = rule?.assigneeId ?? null}
async function saveRule () {await action(async () => {const segment = segments.value.find(s => s.id === ruleSegmentId.value); const payload = {name:ruleName.value,segmentId:ruleSegmentId.value,segmentVersion:segment?.version,assigneeId:assigneeId.value,taskTitle:ruleTitle.value,dueInDays:dueInDays.value,active:ruleActive.value,...(editingRule.value ? {expectedVersion:editingRule.value.version}:{})}; if (editingRule.value) await useApi().put('/api/reports/rules/' + editingRule.value.id,payload); else await useApi().post('/api/reports/rules',payload); ruleDialog.value = false; await refresh()},true)}
async function run (rule:Rule) {await action(async () => {const result = (await useApi().post('/api/reports/rules/' + rule.id + '/run')).data; runMessage.value = result.created + ' tasks created. ' + (result.message ?? ''); await refresh()})}
async function download (path:string, params:Record<string,string>, name:string) {await action(async () => {const result = await useApi().get(path,{params,responseType:'blob'}); const url = URL.createObjectURL(result.data); const link = document.createElement('a'); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url)})}
function money (minor:number,currency:string) {const formatter = new Intl.NumberFormat(undefined,{style:'currency',currency}); return formatter.format(minor / 10 ** (formatter.resolvedOptions().maximumFractionDigits ?? 2))}
onMounted(async () => {await loadSummary(); await action(refresh)})
</script>
<style scoped>.attendance-chart {display:grid;gap:12px;margin-top:20px}.attendance-chart > div {display:flex;align-items:center;gap:12px;font-size:11px;color:var(--workspace-muted)}.attendance-chart meter {flex:1;min-width:0;height:12px}.attendance-chart span {flex-shrink:0}</style>
